    uint32_t n = input_len() / 2;
    if (n < 8) return 0;
    for (uint32_t i = 7; i < n; i++) {
        int32_t acc = 0;
        for (uint32_t k = 0; k < 8; k++) {
            int32_t p = coef[k] * sample(i - k);
            acc = sat_add(acc, p);
        }
        acc = sat_add(acc, 16384);
        int32_t y = acc >> 15;
        if (y > 32767) y = 32767;
        if (y < -32768) y = -32768;
        emit(y);
    }
    return 0;
